import React, { useState } from 'react';
import SectionHeading from './SectionHeading';
import Reveal from './Reveal';
import { projects, projectCategories } from '../data/content';

export default function Projects() {
  const [filter, setFilter] = useState('all');

  const visible = filter === 'all' ? projects : projects.filter((p) => p.categories.includes(filter));

  return (
    <section id="projects" className="py-20 px-4 sm:px-6">
      <div className="max-w-6xl mx-auto">
        <Reveal>
          <SectionHeading eyebrow="// projects" heading="Things I've built" />
        </Reveal>

        <Reveal delay={60}>
          <div className="mt-6 flex flex-wrap gap-2">
            {projectCategories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setFilter(cat.id)}
                className={`px-4 py-1.5 rounded-full text-sm font-mono border transition-colors ${
                  filter === cat.id
                    ? 'bg-indigo-500 text-white border-indigo-500'
                    : 'border-zinc-300 dark:border-zinc-700 text-zinc-600 dark:text-zinc-400 hover:border-indigo-400 hover:text-indigo-500'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </Reveal>

        <div className="mt-6 grid sm:grid-cols-2 gap-4">
          {visible.map((project, idx) => (
            <Reveal key={project.title} delay={(idx % 2) * 80}>
              <div className="h-full rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-6 flex flex-col transition-transform hover:-translate-y-1 hover:shadow-md">
                <div className="flex items-start justify-between gap-3">
                  <h3 className="font-display font-semibold text-lg text-zinc-900 dark:text-zinc-50">
                    {project.title}
                  </h3>
                  <span className="shrink-0 px-2.5 py-1 rounded-full text-xs font-mono bg-zinc-100 dark:bg-zinc-800 text-zinc-500 dark:text-zinc-400">
                    {project.status}
                  </span>
                </div>

                <p className="mt-3 text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed">
                  <span className="font-semibold text-zinc-800 dark:text-zinc-200">Problem — </span>
                  {project.problem}
                </p>
                <p className="mt-2 text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed">
                  <span className="font-semibold text-zinc-800 dark:text-zinc-200">What I built — </span>
                  {project.build}
                </p>

                <div className="mt-3 flex flex-wrap gap-1.5">
                  {project.tech.map((t) => (
                    <span
                      key={t}
                      className="px-2 py-0.5 rounded text-xs font-mono bg-indigo-500/10 text-indigo-600 dark:text-indigo-400"
                    >
                      {t}
                    </span>
                  ))}
                </div>

                <div className="mt-4 pt-4 border-t border-zinc-100 dark:border-zinc-800 text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed">
                  <span className="font-semibold text-emerald-600 dark:text-emerald-400">Impact — </span>
                  {project.impact}
                </div>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
